verification_receipts.patch_excerpt:
diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..c352b77 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -156,7 +156,8 @@ const wrapperInput = {
 };
 const wrapper = profiles.createForkReceiptWrapper({ ...wrapperInput, signingKey });
 const publicKey = crypto.createPublicKey(signingKey);
-assert.equal(profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput }).status, 'verified');
+const wrapperVerification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+assert.equal(wrapperVerification.status, 'verified');
 for (const field of ['fork_id', 'branch_id', 'contract_digest', 'executor_profile_digest', 'execution_receipt_digest', 'observation_digest']) {
   const tampered = copy(wrapper);
   tampered.receipt[field] = field.endsWith('digest') ? `sha256:${'c'.repeat(64)}` : `${tampered.receipt[field]}-tampered`;
@@ -170,6 +171,19 @@ assert.equal(profiles.evaluateModelProof(local, { model: local.model, trusted: t
 assert.equal(profiles.evaluateModelProof(local, { model: 'other-model', trusted: true }).status, 'failed');
 assert.equal(profiles.evaluateModelProof(local, { model: local.model, trusted: false }).status, 'unknown');

+// A cryptographically verified receipt must never launder missing model telemetry
+// into a model match: receipt_status and model_status are independent facts, and
+// an executor profile that never reported its observed model stays 'unknown'
+// even when everything else about the run is fully verified.
+const missingTelemetryVerified = profiles.missionControlExecutorState({
+  profile: local, observation: { trusted: true, source: 'codex-jsonl' }, wrapper, verification: wrapperVerification,
+});
+assert.equal(missingTelemetryVerified.receipt_status, 'verified');
+assert.equal(missingTelemetryVerified.model_status, 'unknown');
+assert.equal(missingTelemetryVerified.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+assert.equal(missingTelemetryVerified.observed_model, null);
+assert.notEqual(missingTelemetryVerified.model_status, 'passed');
+
 const missionUnknown = profiles.missionControlExecutorState({ profile: local, observation: null, wrapper: null });
 assert.equal(missionUnknown.requested_model, local.model);
 assert.equal(missionUnknown.observed_model, null);
